"""Every Workshop hook file name generated by the e2e harnesses must satisfy the daemon's HOOK_NAME rule (found when a 47-character name was rejected)."""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "scripts" / "workshop"))
sys.path.insert(0, str(ROOT / "scripts"))

HOOK_NAME = re.compile(r"^[a-z0-9][a-z0-9._-]{0,40}$")


def _daemon_rule():
    src = (ROOT / "packages/debian/hscl-workshop/usr/lib/hscl/workshop/hscl_workshopd.py").read_text(encoding="utf-8")
    m = re.search(r'^HOOK_NAME = re\.compile\(r"(.+)"\)', src, re.M)
    assert m, "HOOK_NAME not found in the daemon"
    return re.compile(m.group(1))


def test_luks_and_standard_hook_names_fit():
    import e2e_cli
    import e2e_luks_boot

    rule = _daemon_rule()
    names = [f"luks-{k.replace('_', '-')}.sh" for k in e2e_luks_boot.CHECKS]
    names += [f"std-{k.replace('_', '-')}.sh" for k in e2e_cli.CHECKS]
    bad = [n for n in names if not rule.match(n)]
    assert not bad, bad


def test_png_pixel_reader_roundtrip():
    import struct
    import zlib

    import e2e_luks_boot as m

    w, h = 4, 3
    raw = b"".join(b"\x00" + bytes([(x * 10 + y) % 256 for x in range(w) for _ in range(3)]) for y in range(h))

    def chunk(t, d):
        return struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d) & 0xFFFFFFFF)

    png = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)) + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b"")
    assert m.png_pixel(png, 0.0, 0.0) == (0, 0, 0)
    assert m.png_pixel(png, 0.99, 0.99) == (32, 32, 32)
    assert not m._unlock_field_visible(png)
